package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

/** Gives selected people a grade together. Each is edited on its own, as the person form would edit
 *  them, keeping their name and terms, so one that cannot be changed is left as it is and the others
 *  still change. */
@Service
public class BulkGradeService {

    private final PersonService service;
    private final PersonRepository people;
    private final SettingService settings;
    private final SheetRepository sheets;

    public BulkGradeService(PersonService service, PersonRepository people, SettingService settings,
            SheetRepository sheets) {
        this.service = service;
        this.people = people;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Give the people of these ids the grade from the from-date (none: the sheet's today), in list
     *  order: the order they were added. An id not of the sheet is left out. The people changed, in
     *  the order they were changed. A viewer changes no one, nor does anyone on an archived sheet. */
    public List<Person> grade(String sheetId, String user, Collection<Long> ids, Grade grade, LocalDate from) {
        if (settings.roleOf(sheetId, user) == Role.VIEWER || sheets.isArchived(sheetId)) return List.of();
        Set<Long> selected = new LinkedHashSet<>(ids);
        List<Person> changed = new ArrayList<>();
        for (Person person : people.findInListOrder(sheetId)) {
            if (!selected.contains(person.getId())) continue;
            try {
                changed.add(service.regrade(sheetId, user, person.getId(), person.getVersion(), grade, from));
            } catch (ResponseStatusException notChanged) {
                // Left as it is: someone else saved the person at the same moment.
            }
        }
        return changed;
    }
}
package net.officefloor.hq.app;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.server.ResponseStatusException;

/**
 * Refuses every change a viewer of a sheet asks for: any request on a sheet other than reading it
 * (a GET, or loading the sheet) is refused before it reaches its controller, so it writes nothing.
 * The bulk changes are let through: a viewer's bulk change is answered with every selected claim
 * refused (see {@code BulkChangeService}), a viewer's bulk grade with no one changed (see
 * {@code BulkGradeService}), a viewer's bulk retire with no one retired (see {@code BulkRetireService}),
 * a viewer's generate of the plans' claims with none made (see {@code PlanService}), and a viewer's
 * generate of monthly periods with none made (see {@code PeriodService}).
 * A clone is let through too: it changes nothing on the sheet, and only a steward may make one (see
 * {@code CloneService}), so an archived sheet can still be cloned.
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    /** The path of a sheet's requests; the sheet id is the segment after it. */
    public static final String SHEETS = "/api/sheets/";

    static final Set<String> LET_THROUGH = Set.of("load", "claims/open", "claims/settle", "claims/reassign", "claims/redate", "claims/void", "people/grade", "clone",
            "people/retire", "plans/generate", "periods/generate");

    private final SettingService settings;

    public ViewerGuard(SettingService settings) {
        this.settings = settings;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod())) return true;
        String path = request.getRequestURI().substring(request.getContextPath().length());
        String header = request.getHeader(SignedInUser.HEADER);
        if (!path.startsWith(SHEETS) || header == null || header.isBlank()) return true;
        String rest = path.substring(SHEETS.length());
        int slash = rest.indexOf('/');
        if (slash < 0 || LET_THROUGH.contains(rest.substring(slash + 1))) return true;
        String sheetId = URLDecoder.decode(rest.substring(0, slash), StandardCharsets.UTF_8).trim();
        if (settings.roleOf(sheetId, SignedInUser.name(header)) == Role.VIEWER) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer cannot change anything.");
        }
        return true;
    }
}
package net.officefloor.hq.app;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.server.ResponseStatusException;

/**
 * Refuses every change asked for on an archived sheet: any request on a sheet other than reading it
 * (a GET, or loading the sheet) is refused before it reaches its controller, so it writes nothing.
 * As for a viewer, the bulk changes are let through and answered with every selected claim refused
 * (see {@code BulkChangeService}), and the bulk grade with no one changed (see {@code BulkGradeService}).
 */
@Component
public class ArchiveGuard implements HandlerInterceptor {

    private final SheetRepository sheets;

    public ArchiveGuard(SheetRepository sheets) {
        this.sheets = sheets;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod())) return true;
        String path = request.getRequestURI().substring(request.getContextPath().length());
        if (!path.startsWith(ViewerGuard.SHEETS)) return true;
        String rest = path.substring(ViewerGuard.SHEETS.length());
        int slash = rest.indexOf('/');
        if (slash < 0 || ViewerGuard.LET_THROUGH.contains(rest.substring(slash + 1))) return true;
        String sheetId = URLDecoder.decode(rest.substring(0, slash), StandardCharsets.UTF_8).trim();
        if (sheets.isArchived(sheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived: nothing on it can be changed.");
        }
        return true;
    }
}

